sketch:
// Ultrasonic — a tape measure made of sound.
//
// TRIG gets a 10 microsecond pulse; the sensor sends a chirp and raises ECHO
// for as long as the sound takes to come back. pulseIn() measures that on the
// sketch's own clock, and 58 microseconds is one centimetre there and back.
// Move the Distance slider in the properties strip and watch the reading.

const int TRIG = 7;
const int ECHO = 8;

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
}

void loop() {
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long echo = pulseIn(ECHO, HIGH, 30000);
  Serial.print(echo / 58);
  Serial.println(" cm");
  delay(200);
}
